export const CODE: Record<string, string> = {
  "brain.py": "\"\"\"16-rag-cli brain - the smallest useful Cosmonapse system.\n\n    ONE Neuron    neurons/rag.py        a stock LLM Neuron + three decorators\n    ONE Engram    engram/web_memory.py  BM25 over web page chunks\n    ONE Effector  effector/web.py       search + fetch\n\nTopology - three Dendrites on one Synapse\n------------------------------------------\n    engram-host   hosts web-memory              worker\n    web-node      hosts the web Effector        worker\n    rag-node      hosts the rag Axon, and the   orchestrator\n                  CLI dispatches from it\n\nA Dendrite that both originates and hosts work is supported (loopback\nSignals are handled), so the third node doubles as the CLI's orchestrator\nrather than adding a fourth.\n\nThere is no agent loop and no orchestration code in this file. ``ask()``\ndispatches ONE capability-routed TASK and waits for the trace's FINAL.\nEverything in between is declared next to the Neuron as decorators\n(@AXON.before_task / @AXON.detects_output / @AXON.host.on_agent_output),\nand rides Signals on the same trace:\n\n    TASK         -> rag-node      the question\n    RECALL       -> engram-host   what do we already know?\n    TOOL_CALL    -> web-node      search, then fetch each result  (web path)\n    IMPRINT      -> engram-host   every chunk of every page       (web path)\n    RECALL       -> engram-host   the same query, now answerable  (web path)\n    AGENT_OUTPUT <- rag-node      the grounded answer\n    FINAL        <- rag-node      the chain handler concludes the trace\n\nOne question is one trace, so ``cosmo prism --tail`` shows that entire list as\na single chain. Split it across three machines by pointing SYNAPSE_URL at\na shared synapse: nothing here changes, only which process calls\nbuild_rag(). That is what the bindings buy - the Neuron addresses \"web\",\nnever a host or a port.\n\"\"\"\nfrom __future__ import annotations\n\nfrom cosmonapse import Dendrite, SignalType\n\nfrom config import HEARTBEAT_S, NAMESPACE, TOP_K\nfrom effector import web\nfrom engram import web_memory\nfrom neurons import rag\n\n\ndef build_rag(synapse):\n    \"\"\"Stand the three Dendrites up on a Synapse. Returns (dendrites, cli).\n\n    ``attach_engram`` / ``attach_effector`` / ``attach_axon`` is the whole\n    wiring API - no registry, no handler tables, no manual subscriptions.\n    The Axon's chain handler self-registers on announce\n    (@AXON.host.on_agent_output, declared in neurons/rag.py), so nothing\n    below hand-wires an @node.on_* handler. Effectors and Engrams need no\n    registration at all - attaching is enough.\n\n    Liveness is deliberately quiet: a demo does not need 30s beats, so\n    `cosmo prism --tail` shows the chain, not chatter.\n    \"\"\"\n    liveness = {\"heartbeat_s\": HEARTBEAT_S, \"reregister_on_heartbeat\": False}\n\n    host = Dendrite(synapse=synapse, namespace=NAMESPACE,\n                    dendrite_id=\"engram-host\", role=\"worker\", **liveness)\n    host.attach_engram(web_memory.ENGRAM)   # REGISTERs + services it\n\n    tools = Dendrite(synapse=synapse, namespace=NAMESPACE,\n                     dendrite_id=\"web-node\", role=\"worker\", **liveness)\n    tools.attach_effector(web.EFFECTOR)   # TOOL_CALLs are not role-gated\n\n    node = Dendrite(synapse=synapse, namespace=NAMESPACE,\n                    dendrite_id=\"rag-node\", role=\"orchestrator\", **liveness)\n    node.attach_axon(rag.AXON)\n\n    return [host, tools, node], node\n\n\nasync def ask(cli, question: str, *, top_k: int = TOP_K,\n              force_web: bool = False, timeout_s: float = 180.0) -> dict:\n    \"\"\"One TASK out, one FINAL back. The entire edge of the system.\"\"\"\n    sig = await cli.dispatch_and_wait(\n        capabilities=[\"rag\"],\n        input={\"question\": question, \"top_k\": top_k, \"force_web\": force_web},\n        scope=\"terminal\",       # resolve on FINAL / ERROR only\n        finalize=False,         # the Axon's chain handler owns FINAL\n        timeout_s=timeout_s,\n    )\n    if sig.type is SignalType.ERROR:\n        raise RuntimeError(sig.payload.get(\"message\") or \"ask failed\")\n    return sig.payload[\"result\"]\n",
  "cli.py": "\"\"\"rag-cli - a RAG you can talk to that fills its own memory.\n\n    python cli.py \"what is the cosmonapse protocol\"   # one-shot\n    python cli.py                                     # REPL\n    python cli.py --memory                            # what it knows\n\nOne Neuron, one Engram, one Effector, three Dendrites.\n\nIt prefers a dev Synapse - a real TCP broker - because that is what makes\nthe Signals watchable. Start one in another terminal and point a doppler\nat it:\n\n    cosmo synapse start memory --namespace=rag-cli\n    cosmo prism --tail --url=cosmo://127.0.0.1:7070 -n rag-cli\n\nIf nothing is listening, the CLI says so and falls back to an in-process\nMemorySynapse, so the demo still runs. Set SYNAPSE_URL to override the\naddress (it defaults to the one `cosmo synapse start` prints).\n\nConfig comes from ../.env (cosmonapse-examples/.env); it needs a real\nHF_TOKEN. The Effector wraps an MCP server run through uvx, so `uv` must\nbe on PATH - it spawns lazily, on the first search.\n\nRun:\n    pip install cosmonapse httpx python-dotenv mcp\n    python cli.py \"...\"\n\"\"\"\nfrom __future__ import annotations\n\nimport argparse\nimport asyncio\nimport json\nimport os\nimport sys\nimport time\nfrom contextlib import AsyncExitStack\n\nfrom cosmonapse import MemorySynapse, connect_synapse\n\nfrom brain import ask, build_rag\nfrom effector import web\nfrom config import NAMESPACE, TOP_K\nfrom engram import web_memory\n\n#: What `cosmo synapse start memory` prints by default.\nDEV_SYNAPSE_URL = \"cosmo://127.0.0.1:7070\"\n\nDIM, CYAN, GREEN, BOLD, RESET = (\n    \"\\033[2m\", \"\\033[36m\", \"\\033[32m\", \"\\033[1m\", \"\\033[0m\")\n\nHELP = \"\"\"commands:\n  <question>   ask - recall first, hit the web only if memory is thin\n  :web <q>     force a fresh web pass even if memory would have answered\n  :memory      what the engram holds right now\n  :help        this help\n  :quit        leave (also :exit, ctrl-d)\"\"\"\n\n\ndef _memory_report() -> str:\n    pages = web_memory.pages()\n    st = web_memory.STATS\n    lines = [f\"engram {web_memory.ENGRAM_ID}: {web_memory.size()} chunk(s) \"\n             f\"from {len(pages)} page(s)\",\n             f\"  {st['recalls']} recall(s), {st['hits']} hit(s) returned, \"\n             f\"{st['evicted']} chunk(s) evicted\"]\n    lines += [f\"  - {u}\" for u in pages[:12]]\n    if len(pages) > 12:\n        lines.append(f\"  ... and {len(pages) - 12} more\")\n    return \"\\n\".join(lines)\n\n\ndef _render(result: dict, elapsed: float) -> None:\n    src = result.get(\"source\", \"?\")\n    badge = (f\"{GREEN}memory{RESET}\" if src == \"memory\"\n             else f\"{CYAN}web{RESET}\")\n    extra = \"\"\n    if src == \"web\":\n        extra = (f\", {result.get('indexed', 0)} chunk(s) indexed from \"\n                 f\"{len(result.get('pages') or [])} page(s)\")\n    print(f\"\\n{BOLD}answer{RESET}  {DIM}[{badge}{DIM}, {elapsed:.1f}s{extra}]\"\n          f\"{RESET}\")\n    print(result.get(\"answer\", \"\").rstrip())\n    sources = result.get(\"sources\") or []\n    if sources:\n        label = \"sources\" if result.get(\"cited\") else \"passages seen (uncited)\"\n        print(f\"\\n{DIM}{label}{RESET}\")\n        for s in sources:\n            print(f\"{DIM}  [{s['n']}] {s.get('title') or ''}{RESET}\")\n            print(f\"{DIM}      {s.get('url')}  (bm25 {s.get('score')}){RESET}\")\n    print()\n\n\nasync def _ask_one(cli, question: str, *, top_k: int, force_web: bool,\n                   timeout_s: float) -> None:\n    t0 = time.monotonic()\n    try:\n        result = await ask(cli, question, top_k=top_k, force_web=force_web,\n                           timeout_s=timeout_s)\n    except asyncio.TimeoutError:\n        print(\"! timed out\", file=sys.stderr)\n    except RuntimeError as exc:\n        print(f\"! failed: {exc}\", file=sys.stderr)\n    else:\n        _render(result, time.monotonic() - t0)\n\n\nasync def _repl(cli, *, top_k: int, timeout_s: float) -> None:\n    print(f\"{BOLD}rag-cli{RESET} - ask a question, or :help\")\n    loop = asyncio.get_running_loop()\n    while True:\n        try:\n            line = await loop.run_in_executor(None, input, \"\\n? \")\n        except (EOFError, KeyboardInterrupt):\n            print()\n            return\n        q = line.strip()\n        if not q:\n            continue\n        if q in (\":q\", \":quit\", \":exit\"):\n            return\n        if q in (\":h\", \":help\", \"?\"):\n            print(HELP)\n            continue\n        if q == \":memory\":\n            print(_memory_report())\n            continue\n        force = q.startswith(\":web \")\n        await _ask_one(cli, q[5:].strip() if force else q, top_k=top_k,\n                       force_web=force, timeout_s=timeout_s)\n\n\ndef _wire_trace_view(cli) -> None:\n    \"\"\"Everything below is OBSERVATION ONLY - the CLI's Dendrite\n    subscribing to Signals that were crossing the wire anyway. Nothing\n    here is required for the system to work; delete it and the answers\n    are identical.\"\"\"\n\n    @cli.on_tool_call\n    async def show_call(sig):\n        p = sig.payload\n        print(f\"{DIM}  * {p.get('tool')} \"\n              f\"{json.dumps(p.get('args') or {})[:100]}{RESET}\")\n\n    @cli.on_tool_result\n    async def show_result(sig):\n        if sig.payload.get(\"error\"):\n            print(f\"{DIM}    x {str(sig.payload['error'])[:100]}{RESET}\")\n\n    @cli.on_recall_signal\n    async def show_recall(sig):\n        q = (sig.payload.get(\"query\") or {}).get(\"text\", \"\")\n        print(f\"{DIM}  ~ recall {str(q)[:70]!r}{RESET}\")\n\n    @cli.on_recalled\n    async def show_recalled(sig):\n        hits = sig.payload.get(\"hits\") or []\n        print(f\"{DIM}    -> {len(hits)} hit(s){RESET}\")\n\n    imprints = {\"n\": 0}\n\n    @cli.on_imprinted\n    async def show_imprint(sig):\n        imprints[\"n\"] += 1\n        print(f\"{DIM}  + imprint {imprints['n']}\\r{RESET}\", end=\"\", flush=True)\n\n\nasync def main() -> int:\n    ap = argparse.ArgumentParser(\n        prog=\"cli.py\", description=\"A Cosmonapse RAG with a live web memory.\")\n    ap.add_argument(\"question\", nargs=\"*\", help=\"omit for an interactive REPL\")\n    ap.add_argument(\"--top-k\", type=int, default=TOP_K,\n                    help=f\"passages fed to the model (default {TOP_K})\")\n    ap.add_argument(\"--web\", action=\"store_true\",\n                    help=\"force a fresh web pass, skipping the memory check\")\n    ap.add_argument(\"--timeout\", type=float, default=180.0,\n                    help=\"per-question timeout in seconds (default 180)\")\n    ap.add_argument(\"--memory\", action=\"store_true\",\n                    help=\"print what the engram holds, then exit\")\n    ap.add_argument(\"--quiet\", action=\"store_true\",\n                    help=\"hide the live Signal trace\")\n    args = ap.parse_args()\n\n    # Prefer the dev Synapse: a real broker means the Signals are visible\n    # to `cosmo prism --tail`, which is the whole reason to look at this example.\n    # Nothing listening is not an error though - fall back to the in-process\n    # bus and say so, because a ConnectionRefusedError traceback with a\n    # camera pointed at the terminal is a bad time.\n    url = os.environ.get(\"SYNAPSE_URL\") or DEV_SYNAPSE_URL\n    synapse, shared = None, False\n    try:\n        synapse = await connect_synapse(url)\n        shared = True\n        print(f\"{DIM}synapse: {url}{RESET}\")\n    except OSError as exc:\n        print(f\"{DIM}synapse: {url} unreachable ({type(exc).__name__}) - \"\n              f\"using an in-process bus.{RESET}\\n\"\n              f\"{DIM}          for a watchable one:  \"\n              f\"cosmo synapse start memory --namespace={NAMESPACE}{RESET}\",\n              file=sys.stderr)\n    if synapse is None:\n        synapse = MemorySynapse()\n        await synapse.connect()\n\n    dendrites, cli = build_rag(synapse)\n    async with AsyncExitStack() as stack:\n        for d in dendrites:\n            await stack.enter_async_context(d)\n        if not args.quiet:\n            _wire_trace_view(cli)\n\n        if args.memory:\n            print(_memory_report())\n        elif args.question:\n            await _ask_one(cli, \" \".join(args.question), top_k=args.top_k,\n                           force_web=args.web, timeout_s=args.timeout)\n        else:\n            await _repl(cli, top_k=args.top_k, timeout_s=args.timeout)\n\n    # A served Effector has no close hook (LifecycleHooks stops at\n    # on_connect / on_refresh / on_schedule), so the process that started\n    # the MCP subprocess closes it. See effector/web.py:aclose.\n    await web.aclose()\n    if not shared:\n        await synapse.close()\n    return 0\n\n\nif __name__ == \"__main__\":\n    try:\n        raise SystemExit(asyncio.run(main()))\n    except KeyboardInterrupt:\n        raise SystemExit(130)\n",
  "config.py": "\"\"\"Shared settings for 16-rag-cli - the whole configuration surface.\n\nLives at the package root so every module can import it as\n``from config import ...`` when the example is run with ``python cli.py``.\n\"\"\"\nfrom __future__ import annotations\n\nimport os\nfrom pathlib import Path\n\nfrom dotenv import load_dotenv\n\nfrom cosmonapse import Neuron\n\nROOT = Path(__file__).resolve().parent          # the 16-rag-cli/ dir\nload_dotenv(ROOT.parent / \".env\")               # cosmonapse-examples/.env\n\nNAMESPACE = \"rag-cli\"\n\nHF_ROUTER = os.environ.get(\"HF_ROUTER\", \"https://router.huggingface.co\")\nMODEL = os.environ.get(\"RAGCLI_MODEL\", \"meta-llama/Llama-3.1-8B-Instruct\")\nMAX_NEW_TOKENS = int(os.environ.get(\"RAGCLI_MAX_NEW_TOKENS\", \"700\"))\n\n# Retrieval knobs. Together, MEMORY_HITS + MIN_COVERAGE are the entire\n# \"do I already know this?\" policy - see neurons/rag.py.\nTOP_K = int(os.environ.get(\"RAGCLI_TOP_K\", \"5\"))       # chunks fed to the model\nMEMORY_HITS = int(os.environ.get(\"RAGCLI_MEMORY_HITS\", \"3\"))\n# Fraction of the question's content words that must appear in what memory\n# returned. A raw BM25 floor would be the obvious knob and is the wrong one:\n# BM25's idf term collapses on a small corpus, so the same threshold means\n# \"everything\" at 5 chunks and \"nothing\" at 5000. Coverage is scale-free.\nMIN_COVERAGE = float(os.environ.get(\"RAGCLI_MIN_COVERAGE\", \"0.6\"))\n# A passage is only shown to the model if it scores at least this fraction\n# of the best hit's score. Absolute BM25 floors do not survive a corpus\n# that changes size; a ratio to the top hit does. This is what keeps an\n# unrelated page out of the prompt when the corpus is small enough that\n# everything scores something.\nMIN_SCORE_RATIO = float(os.environ.get(\"RAGCLI_MIN_SCORE_RATIO\", \"0.55\"))\n\n# Query-side term filtering, shared by the retriever and the coverage gate\n# so the two never disagree about what a question is \"about\". Documents are\n# indexed whole - only the QUERY is filtered, which is standard BM25 and is\n# the difference between \"last 3 presidents of the USA\" meaning\n# {last, presidents, usa} and it also meaning {the, of, us, 3}.\nMIN_TERM_CHARS = 3\nSTOPWORDS = frozenset({\n    \"the\", \"and\", \"for\", \"are\", \"was\", \"were\", \"what\", \"which\", \"who\",\n    \"how\", \"why\", \"when\", \"does\", \"did\", \"can\", \"with\", \"from\", \"that\",\n    \"this\", \"into\", \"about\", \"its\", \"you\", \"your\", \"has\", \"have\", \"list\",\n    \"more\", \"most\", \"then\", \"than\", \"there\", \"their\", \"them\", \"some\",\n})\n\n# Web knobs.\nSEARCH_RESULTS = int(os.environ.get(\"RAGCLI_SEARCH_RESULTS\", \"5\"))\nFETCH_PAGES = int(os.environ.get(\"RAGCLI_FETCH_PAGES\", \"3\"))\nFETCH_CHARS = int(os.environ.get(\"RAGCLI_FETCH_CHARS\", \"6000\"))\nCHUNK_CHARS = int(os.environ.get(\"RAGCLI_CHUNK_CHARS\", \"900\"))\nCHUNK_OVERLAP = int(os.environ.get(\"RAGCLI_CHUNK_OVERLAP\", \"150\"))\n# Below this a \"page\" is a stub, a consent wall, or an error the server\n# handed back as prose - not something worth remembering.\nMIN_PAGE_CHARS = int(os.environ.get(\"RAGCLI_MIN_PAGE_CHARS\", \"400\"))\n\n# The engram is in-process and grows every time the agent reads a page, so\n# a long REPL session needs a ceiling. Enforced on the memory side, by\n# @ENGRAM.host.on_imprint_signal - see engram/web_memory.py.\nMAX_CHUNKS = int(os.environ.get(\"RAGCLI_MAX_CHUNKS\", \"400\"))\n\nHEARTBEAT_S = float(os.environ.get(\"RAGCLI_HEARTBEAT_S\", \"300\"))\n\n# Grounding is a constraint on where the answer comes from, not a subject\n# the answer is about. The earlier draft said \"using ONLY the provided\n# context passages\", and the model dutifully opened with \"I can only answer\n# based on the provided context passages\" - narrating its own instructions\n# instead of answering. Emphatic rules get echoed. So: state the constraint\n# once, plainly, and spend the rest of the prompt on voice.\nSYSTEM_PROMPT = (\n    \"Answer from the context passages below, and not from anything else \"\n    \"you know. The passages are labelled [n] - cite the ones you draw on \"\n    \"inline, like [1] or [2].\\n\\n\"\n    \"Write the answer itself. Do not describe the passages, do not explain \"\n    \"what you are or are not able to do with them, and do not mention the \"\n    \"context at all - the reader can see it. If it does not cover the \"\n    \"question, say what is missing in one sentence and stop; do not fill \"\n    \"the gap from memory, and do not half-answer from a passage that only \"\n    \"mentions the topic. Three or four sentences, plain prose.\"\n)\n\n\ndef hf_token() -> str:\n    token = os.environ.get(\"HF_TOKEN\", \"\")\n    if not token or token.startswith(\"hf_xxx\"):\n        raise RuntimeError(\"Set a real HF_TOKEN in cosmonapse-examples/.env\")\n    return token\n\n\ndef llm(model: str = MODEL) -> Neuron:\n    \"\"\"The Neuron. A hosted chat model, and nothing else.\"\"\"\n    return Neuron(\n        source=\"huggingface\", endpoint=HF_ROUTER, model=model,\n        api_key=\"dummy\", use_chat_api=True,\n        max_new_tokens=MAX_NEW_TOKENS, temperature=0.2,\n    )\n",
  "effector/web.py": "\"\"\"web - THE Effector, written the way the SDK wants it: decorators.\n\n``Effector.serve()`` gives you the one protocol hook that matters. A\nTOOL_CALL arrives, ``@EFFECTOR.on_tool_call`` runs, and its RETURN VALUE\nis emitted as the TOOL_RESULT - no manual publish, no dispatch table in\nthe SDK. What happens in between is your code; here it is one MCP server\n(DuckDuckGo, via uvx) exposing both halves of \"read the internet\":\n\n    search(query, max_results)   -> titles, snippets, URLs\n    fetch(url, max_length)       -> that page as clean text\n                                    (the server calls it ``fetch_content``;\n                                    the shim below is the whole reason a\n                                    caller never has to know that)\n\nThe decorator surface, matching Axon and Engram:\n\n    @EFFECTOR.on_tool_call      the tool itself - return value IS the reply\n    @EFFECTOR.on_connect        fire-once when the hosting Dendrite starts\n    @EFFECTOR.host.on_final     a HOST-side reaction, replayed onto the\n                                Dendrite that attaches this Effector. Used\n                                here to drop the per-trace fetch memo when\n                                the trace ends - the action-side twin of\n                                @AXON.host.on_agent_output.\n\nHandlers run in registration order and the first non-None return answers,\nso a policy gate (rate limit, allowlist, budget) can sit in front of the\nreal handler without either knowing about the other.\n\nSwap this file for a Playwright driver, an internal search API, or a\nmocked dict, and nothing else in the example changes. smoke_test.py does\nexactly that.\n\"\"\"\nfrom __future__ import annotations\n\nfrom typing import Any\n\nfrom cosmonapse import Effector, Neuron\n\n# The [browser] extra pulls in curl_cffi. DuckDuckGo blocks plain-httpx TLS\n# fingerprints from some networks, and the server's default \"auto\" backend\n# falls back to Chrome impersonation when that happens - but only if the\n# extra is installed. Costs one package on the first uvx run and turns an\n# intermittent, silent, on-camera failure into a non-event.\nSERVER = [\"--from\", \"duckduckgo-mcp-server[browser]\", \"duckduckgo-mcp-server\"]\n\nEFFECTOR = Effector.serve(effector_id=\"web-effector\", effector_kind=\"web\")\n\n# The MCP Neuron owns the subprocess: it spawns lazily on the first call.\n# Nothing spawns at import time.\n_MCP = Neuron(source=\"mcp\", command=\"uvx\", args=SERVER)\n\n#: trace_id -> {url: page text}. One question fetches several pages; a\n#: re-run of the same question on the same trace should not pay twice.\n_SEEN: dict[str, dict[str, str]] = {}\n\n\n@EFFECTOR.on_connect\nasync def announce(fx) -> None:\n    \"\"\"Fire-once when the hosting Dendrite starts. Deliberately does not\n    touch the MCP server - spawning it here would pay the uvx cost at\n    boot for a session that may never search.\"\"\"\n    _SEEN.clear()\n\n\ndef _shape(tool: str, a: dict[str, Any]) -> tuple[str, dict[str, Any]]:\n    \"\"\"Caller-facing name -> the server's own name and argument shape.\"\"\"\n    if tool == \"search\":\n        return \"search\", {\"query\": str(a.get(\"query\", \"\")),\n                          \"max_results\": int(a.get(\"max_results\", 5))}\n    if tool == \"fetch\":\n        return \"fetch_content\", {\"url\": str(a.get(\"url\", \"\")),\n                                 \"max_length\": int(a.get(\"max_length\", 6000))}\n    raise ValueError(f\"unknown tool {tool!r}; expected search | fetch\")\n\n\n@EFFECTOR.on_tool_call\nasync def handle(tool: str, args: dict[str, Any], *, trace_id: str | None = None):\n    \"\"\"THE tool. Whatever this returns becomes the TOOL_RESULT; a raise\n    becomes ``error`` on it, and a tool error never terminates the parent\n    TASK. ``trace_id`` is injected because it is declared - so is\n    ``call_id`` and ``deadline_ms`` if a handler asks for them.\"\"\"\n    args = dict(args or {})\n\n    # Within one trace, the same URL is only ever read once.\n    if tool == \"fetch\" and trace_id:\n        cached = _SEEN.get(trace_id, {}).get(str(args.get(\"url\", \"\")))\n        if cached is not None:\n            return {\"response\": cached, \"cached\": True}\n\n    server_tool, server_args = _shape(tool, args)\n    out = await _MCP({\"tool\": server_tool, \"arguments\": server_args}, [])\n\n    body = str(out.get(\"response\") or \"\")\n    if out.get(\"is_error\"):\n        raise RuntimeError(body or f\"{tool} failed\")\n\n    # The server reports failures as PROSE with a 200 - an empty search, a\n    # 403, a timeout - so is_error stays False. Left alone, that error text\n    # gets chunked and imprinted as though it were page content, and then\n    # ranks against real passages. Promote them to real tool errors so the\n    # caller skips the page instead of learning it.\n    if body.startswith(\"Error:\") or body.startswith(\n            \"An error occurred while searching:\"):\n        raise RuntimeError(body[:200])\n    if tool == \"search\" and body.startswith(\"No results were found\"):\n        raise RuntimeError(body[:200])\n\n    if tool == \"fetch\" and trace_id:\n        _SEEN.setdefault(trace_id, {})[str(args.get(\"url\", \"\"))] = body\n    return out\n\n\n@EFFECTOR.host.on_final\nasync def forget(sig) -> None:\n    \"\"\"Host-side: the trace is over, drop its fetch memo. Without this the\n    dict grows for the life of the process - the reason a per-trace cache\n    wants a per-trace cleanup signal, and the reason this decorator\n    exists on the action side at all.\"\"\"\n    _SEEN.pop(sig.trace_id, None)\n\n\nasync def aclose() -> None:\n    \"\"\"Tear down the MCP subprocess.\n\n    NOTE: LifecycleHooks gives a served Effector ``on_connect`` /\n    ``on_refresh`` / ``on_schedule`` but no close hook - ``close()`` only\n    cancels schedule loops - so an Effector that owns a resource has\n    nowhere to release it. Until the SDK grows ``@on_close``, the process\n    that started the stack closes it; cli.py calls this beside\n    ``synapse.close()``. An Effector subclass with its own ``close()``\n    (the pre-decorator form of this file) is the other way round it.\n    \"\"\"\n    await _MCP.aclose()\n",
  "engram/web_memory.py": "\"\"\"web-memory - THE Engram, coded as signal decorators.\n\n``Engram.serve()`` is the memory-side twin of ``Effector.serve()``. A\nRECALL arrives, ``@ENGRAM.on_recall`` runs, and what it RETURNS is\npublished as the RECALLED hits; an IMPRINT arrives, ``@ENGRAM.on_imprint``\nruns, and what it returns becomes the IMPRINTED receipt. There is no ABC\nto implement and no reply to publish by hand.\n\n    @ENGRAM.serves        can_serve gate - which queries this can answer\n    @ENGRAM.on_recall     RECALL  -> these Hits become RECALLED\n    @ENGRAM.on_imprint    IMPRINT -> this id becomes the IMPRINTED receipt\n    @ENGRAM.host.on_recalled   a pure OBSERVER, fires after the reply\n\nThe Engram is attached under its own ``engram_id``, so it REGISTERs\nnormally (``engram=True``, ``role=\"engram\"``) and observers - Prism, the\nbrain view - classify it as one node of the right kind. The decorators\nchange where the body lives, nothing else: the hosting Dendrite still\nresolves ``directed.id``, calls in, and publishes the reply with the\nEngram's own attribution.\n\nServicing vs observing\n----------------------\n``@on_recall`` / ``@on_imprint`` ARE the servicing - they run inside the\nDendrite's handling pass, the same position ``@AXON.before_task`` occupies\nfor a Neuron. ``@ENGRAM.host.on_*`` is the other thing: those fire AFTER\nthe reply is already on the wire, so they observe. Writing to the store\nfrom one would double-apply the op. ``mark_used`` below only annotates.\n\nThe store is a BM25-lite inverted index over web page chunks:\n\n    Entry shape (imprint):  {\"text\", \"url\", \"title\", \"chunk_index\",\n                             \"fetched_at\"}\n    Query shape (recall):   {\"text\": str, \"top_k\": int = 5}\n\nThe chunk's ``merge_key`` is ``<url>#<chunk_index>``, so re-reading a page\nupserts its chunks instead of duplicating them.\n\"\"\"\nfrom __future__ import annotations\n\nimport logging\nimport math\nimport re\nimport time\nimport uuid\nfrom collections import Counter\nfrom datetime import datetime, timezone\nfrom typing import Any\n\nfrom cosmonapse import Engram, Hit\n\nfrom config import MAX_CHUNKS, MIN_TERM_CHARS, STOPWORDS\n\nlogger = logging.getLogger(__name__)\n\nENGRAM_ID = \"web-memory\"\nENGRAM_KIND = \"lexical\"\n\n_TOKEN = re.compile(r\"[a-z0-9]+\")\n\nK1, B = 1.5, 0.75                      # BM25 constants\n\n\ndef tokenize(text: str) -> list[str]:\n    \"\"\"Document-side: index everything. df is only meaningful if the\n    postings cover the whole vocabulary.\"\"\"\n    return _TOKEN.findall(text.lower())\n\n\ndef query_terms(text: str) -> list[str]:\n    \"\"\"Query-side: drop stopwords and one/two-character tokens.\n\n    Not cosmetic. idf on a few-hundred-chunk index does not push \"the\" and\n    \"of\" to zero the way it would on a real corpus, so an unfiltered query\n    scores every page that is merely long and English above the page that\n    actually answers it. Filtering the query is where BM25 gets its\n    precision back at this scale - and it makes a truly irrelevant chunk\n    score exactly 0.0, which the loop below already drops.\n    \"\"\"\n    return [t for t in _TOKEN.findall(text.lower())\n            if len(t) >= MIN_TERM_CHARS and t not in STOPWORDS]\n\n\n# ---------------------------------------------------------------------------\n# The store. A plain inverted index - it implements no protocol.\n# ---------------------------------------------------------------------------\n\n_ENTRIES: dict[str, dict[str, Any]] = {}\n_TF: dict[str, Counter] = {}           # entry id -> term freq\n_DF: Counter = Counter()               # term -> doc freq\n_KEYS: dict[str, str] = {}             # merge_key -> entry id\n\n#: What the memory has noticed about itself. Surfaced by the CLI's :memory.\nSTATS = {\"recalls\": 0, \"hits\": 0, \"evicted\": 0}\n\n\ndef _unindex(eid: str) -> None:\n    for term in _TF.pop(eid, ()):\n        _DF[term] -= 1\n        if _DF[term] <= 0:\n            del _DF[term]\n\n\ndef _index(eid: str, entry: dict[str, Any]) -> None:\n    tf = Counter(tokenize(entry.get(\"text\", \"\")))\n    _TF[eid] = tf\n    for term in tf:\n        _DF[term] += 1\n\n\ndef _put(entry: dict[str, Any], merge_key: str | None) -> str:\n    eid = _KEYS.get(merge_key) if merge_key else None\n    if eid:                            # upsert: replace in place\n        _unindex(eid)\n    else:\n        eid = f\"web_{uuid.uuid4().hex[:12]}\"\n        if merge_key:\n            _KEYS[merge_key] = eid\n    _ENTRIES[eid] = dict(entry)\n    _index(eid, _ENTRIES[eid])\n    return eid\n\n\ndef _drop(eid: str) -> None:\n    _unindex(eid)\n    _ENTRIES.pop(eid, None)\n    for k, v in list(_KEYS.items()):\n        if v == eid:\n            del _KEYS[k]\n\n\ndef _age_key(eid: str) -> str:\n    \"\"\"Least-recently-USED, falling back to when it was fetched. A chunk\n    that keeps answering questions keeps its place.\"\"\"\n    e = _ENTRIES[eid]\n    return e.get(\"last_used\") or e.get(\"fetched_at\", \"\")\n\n\ndef _cap() -> int:\n    \"\"\"Keep the index under MAX_CHUNKS, stalest first.\"\"\"\n    over = len(_ENTRIES) - MAX_CHUNKS\n    if over <= 0:\n        return 0\n    for eid in sorted(_ENTRIES, key=_age_key)[:over]:\n        _drop(eid)\n    STATS[\"evicted\"] += over\n    logger.info(\"web-memory: evicted %d chunk(s) to stay under %d\",\n                over, MAX_CHUNKS)\n    return over\n\n\n# ---------------------------------------------------------------------------\n# THE ENGRAM. Attached under its own id, serviced by decorators.\n# ---------------------------------------------------------------------------\n\nENGRAM = Engram.serve(engram_id=ENGRAM_ID, engram_kind=ENGRAM_KIND,\n                      capabilities=[\"bm25\", \"keyword\", \"merge_key\"])\n\n\n@ENGRAM.serves\ndef only_text(query: dict) -> bool:\n    \"\"\"can_serve: decline a vector query if one is ever routed by kind\n    rather than by id. The hosting Dendrite skips responding on False.\"\"\"\n    return \"text\" in query\n\n\n@ENGRAM.on_recall\nasync def search(query: dict, *, deadline_ms=None, min_confidence=None):\n    \"\"\"RECALL -> these Hits become the RECALLED payload.\"\"\"\n    STATS[\"recalls\"] += 1\n    qterms = query_terms(str(query.get(\"text\", \"\")))\n    n = len(_ENTRIES)\n    if not qterms or n == 0:\n        return []\n    top_k = int(query.get(\"top_k\", 5))\n    avgdl = sum(sum(tf.values()) for tf in _TF.values()) / n\n    t0, scored = time.monotonic(), []\n    for eid, entry in _ENTRIES.items():\n        tf = _TF.get(eid, Counter())\n        dl = sum(tf.values()) or 1\n        score = 0.0\n        for term in qterms:\n            f = tf.get(term, 0)\n            if not f:\n                continue\n            idf = math.log(1 + (n - _DF[term] + 0.5) / (_DF[term] + 0.5))\n            score += idf * (f * (K1 + 1)) / (f + K1 * (1 - B + B * dl / avgdl))\n        if score <= 0.0:\n            continue\n        if min_confidence is not None and score < min_confidence:\n            continue\n        scored.append(Hit(id=eid, entry=dict(entry), score=score))\n        if deadline_ms and (time.monotonic() - t0) * 1000 > deadline_ms:\n            break\n    scored.sort(key=lambda h: h.score, reverse=True)\n    return scored[:top_k]\n\n\n@ENGRAM.on_imprint\nasync def write(op: str, entry: dict, *, merge_key=None):\n    \"\"\"IMPRINT -> this id becomes the IMPRINTED receipt.\n\n    The cap runs here because this handler owns the write. Returning None\n    falls through, so an op nothing handles reports ``unhandled imprint\n    op`` instead of silently succeeding.\"\"\"\n    if op in (\"add\", \"append\", \"upsert\", \"merge\"):\n        eid = _put(entry, merge_key)\n        _cap()\n        return eid\n    if op == \"delete\":\n        eid = _KEYS.get(merge_key) if merge_key else entry.get(\"id\")\n        if eid:\n            _drop(eid)\n        return eid\n    return None\n\n\n# ---------------------------------------------------------------------------\n# A pure OBSERVER. Note which signal carries what: the request had the\n# query, only the reply has the hits.\n# ---------------------------------------------------------------------------\n\n@ENGRAM.host.on_recalled\nasync def mark_used(sig):\n    \"\"\"Stamp the entries that answered. This is what turns the cap from\n    least-recently-FETCHED into least-recently-USED, without the agent or\n    the index knowing it happens.\"\"\"\n    hits = sig.payload.get(\"hits\") or []\n    STATS[\"hits\"] += len(hits)\n    now = datetime.now(timezone.utc).isoformat()\n    for h in hits:\n        entry = _ENTRIES.get(h.get(\"id\"))\n        if entry is not None:\n            entry[\"last_used\"] = now\n\n\n# ---------------------------------------------------------------------------\n# Read-only views, for the CLI's :memory command.\n# ---------------------------------------------------------------------------\n\ndef size() -> int:\n    return len(_ENTRIES)\n\n\ndef entries() -> dict[str, dict[str, Any]]:\n    return _ENTRIES\n\n\ndef pages() -> list[str]:\n    \"\"\"Distinct source URLs currently indexed, most-recent-first.\"\"\"\n    seen: dict[str, str] = {}\n    for e in _ENTRIES.values():\n        url = e.get(\"url\")\n        if url and url not in seen:\n            seen[url] = e.get(\"fetched_at\", \"\")\n    return sorted(seen, key=lambda u: seen[u], reverse=True)\n",
  "neurons/rag.py": "\"\"\"rag - THE Neuron: a STOCK LLM Neuron plus three decorators.\n\n``neuron_fn`` is ``llm()`` and nothing else - a hosted chat model that has\nno retrieval code, no tool code, no protocol code, and no idea Cosmonapse\nexists. Everything that makes it a RAG is declared around it, the same way\nevery other example in this repo does it:\n\n    @AXON.before_task      RECALL the engram (dendrite.recall). If memory\n                           does not cover the question, SEARCH and FETCH\n                           through the Effector (dendrite.call_tool), chunk\n                           what comes back, IMPRINT it (dendrite.imprint),\n                           and recall again. Both paths end at one prompt.\n\n    @AXON.detects_output   the model's reply IS the answer; re-attach the\n                           sources it was allowed to cite, and the per-trace\n                           state the hook stashed.\n\n    @AXON.host.on_agent_output(neuron=\"rag\")   THE CHAIN: emit FINAL. A\n                           deferred host decorator - it queues at import\n                           time and is replayed onto whichever Dendrite\n                           hosts this Axon, so brain.py wires nothing.\n\nThe Axon also DECLARES what this Neuron may touch. The bindings are the\nsingle source of truth for addressing: the hooks below reach the Engram and\nthe Effector through the same two ids the bindings publish, so changing a\nbinding changes where the Signals go.\n\n    dendrite.recall(engram_id=...)         RECALL    -> RECALLED\n    dendrite.imprint(engram_id=...)        IMPRINT   -> IMPRINTED\n    dendrite.call_tool(effector_id=...)    TOOL_CALL -> TOOL_RESULT\n\nThose are Signals on the bus, not function calls into a library. Move the\nEngram or the Effector to another machine and this file is untouched.\n\nThere is no agent loop: one TASK in, one FINAL out.\n\"\"\"\nfrom __future__ import annotations\n\nimport re\nfrom datetime import datetime, timezone\n\nfrom cosmonapse import Axon, EffectorBinding, EngramBinding\nfrom cosmonapse.envelope import ambient_trace\n\nfrom config import (CHUNK_CHARS, CHUNK_OVERLAP, FETCH_CHARS, FETCH_PAGES,\n                    MEMORY_HITS, MIN_COVERAGE, MIN_PAGE_CHARS,\n                    MIN_SCORE_RATIO, MIN_TERM_CHARS, SEARCH_RESULTS,\n                    STOPWORDS, SYSTEM_PROMPT, TOP_K, llm)\nfrom engram.web_memory import ENGRAM_ID\n\nEFFECTOR_ID = \"web-effector\"\n\n#: trace_id -> what before_task learned, handed to detects_output. The\n#: house pattern: hooks cannot return values to each other, and the raw\n#: model reply carries none of this.\n_PENDING: dict[str, dict] = {}\n\n_URL = re.compile(r\"https?://[^\\s\\]\\\"'<>]+\")\n_WORD = re.compile(r\"[a-z0-9]+\")\n_CITE = re.compile(r\"\\[(\\d{1,2})\\]\")\n_SKIP = (\"duckduckgo.com\", \"google.com/search\", \"bing.com/search\")\n\n\ndef _terms(question: str) -> set[str]:\n    \"\"\"The question's content words. Same filter the Engram applies to a\n    query (config.STOPWORDS), so the coverage gate below and the retriever\n    can never disagree about what the question is asking for.\"\"\"\n    return {t for t in _WORD.findall(question.lower())\n            if len(t) >= MIN_TERM_CHARS and t not in STOPWORDS}\n\n\n# ---------------------------------------------------------------------------\n# Pure helpers - no I/O.\n# ---------------------------------------------------------------------------\n\ndef _tidy(url: str) -> str:\n    \"\"\"Trim trailing punctuation without eating a balanced paren.\n\n    Wikipedia disambiguators are the reason this exists: naively excluding\n    ')' turns .../The_International_(esports) into .../The_International_\n    (esports, which 404s. Keep a ')' that closes a '(' in the URL itself,\n    drop one that merely closed a sentence.\"\"\"\n    url = url.rstrip(\".,;:!'\\\"\")\n    while url.endswith(\")\") and url.count(\")\") > url.count(\"(\"):\n        url = url[:-1]\n    return url\n\n\ndef _urls(text: str, limit: int) -> list[str]:\n    out: list[str] = []\n    for raw in _URL.findall(text or \"\"):\n        url = _tidy(raw)\n        if any(s in url for s in _SKIP) or url in out:\n            continue\n        out.append(url)\n        if len(out) >= limit:\n            break\n    return out\n\n\ndef _chunks(text: str) -> list[str]:\n    \"\"\"Fixed-width overlapping chunks. Deliberately dumb - a smarter\n    splitter is a better splitter, not a different architecture.\"\"\"\n    body = re.sub(r\"\\n{3,}\", \"\\n\\n\", (text or \"\").strip())\n    step = max(1, CHUNK_CHARS - CHUNK_OVERLAP)\n    return [c for c in (body[i:i + CHUNK_CHARS]\n                        for i in range(0, len(body), step)) if len(c) > 120]\n\n\ndef _title(text: str, url: str) -> str:\n    for line in (text or \"\").splitlines():\n        line = line.strip().lstrip(\"# \").strip()\n        if len(line) > 8:\n            return line[:90]\n    return url\n\n\ndef _passages(hits) -> list[dict]:\n    \"\"\"Hits the model is allowed to see, renumbered 1..n.\n\n    Hits arrive sorted, and every one of them scored above zero - but\n    \"above zero\" is not \"relevant\". On a small index a page can score\n    respectably on one incidental term and still have nothing to do with\n    the question, and a passage in the prompt is an invitation to cite it.\n    So the tail is cut relative to the best hit rather than at a fixed\n    score, which is the only cut that means the same thing at 5 chunks and\n    at 5000.\n    \"\"\"\n    ranked = [{\"text\": h.entry.get(\"text\", \"\"), \"url\": h.entry.get(\"url\", \"\"),\n               \"title\": h.entry.get(\"title\", \"\"),\n               \"score\": round(float(h.score or 0.0), 3)}\n              for h in hits]\n    if not ranked:\n        return []\n    floor = ranked[0][\"score\"] * MIN_SCORE_RATIO\n    kept = [p for p in ranked if p[\"score\"] >= floor]\n    for i, p in enumerate(kept):\n        p[\"n\"] = i + 1\n    return kept\n\n\ndef _covers(question: str, passages: list[dict]) -> bool:\n    \"\"\"The entire \"do I already know this?\" policy: enough passages, and at\n    least ONE of them covering enough of the question's content words.\n\n    Per-passage, not pooled. Pooling the passages together is the obvious\n    implementation and it is wrong: five unrelated pages can between them\n    contain every word of a question none of them answers, which reads as\n    full coverage and skips the web. A single passage that covers the\n    question is evidence; five that each cover a fifth of it is not.\n\n    ``passages`` has already been through the score floor in _passages, and\n    that ordering matters: the count check is only evidence of coverage if\n    the things being counted are relevant. Counting every chunk that scored\n    above zero is how a corpus about something else votes itself sufficient.\n    \"\"\"\n    if len(passages) < MEMORY_HITS:\n        return False\n    terms = _terms(question)\n    if not terms:\n        return True\n    return max(\n        sum(1 for t in terms if t in p[\"text\"].lower()) / len(terms)\n        for p in passages\n    ) >= MIN_COVERAGE\n\n\nAXON = Axon(\n    neuron_id=\"rag\", neuron_fn=llm(), capabilities=[\"rag\"],\n    # \"web\" the memory. directed_id is what lands in the RECALL / IMPRINT\n    # envelope, and what the hooks below address.\n    engrams=[EngramBinding(name=\"web\", directed_id=ENGRAM_ID)],\n    # \"web\" the tool, with its reachable surface pinned to two names.\n    effectors=[EffectorBinding(name=\"web\", directed_id=EFFECTOR_ID,\n                               tools=(\"search\", \"fetch\"))],\n    # THE GATE: effectors= is refused without a tool_standard, because the\n    # standard is how an Axon would recognise a tool call in a model's raw\n    # output. This model answers in prose and the hook issues the calls, so\n    # the parser never matches - the standard keeps the binding legal and\n    # leaves the door open for a model-driven variant.\n    tool_standard=\"codex\",\n)\n\n\n# ---------------------------------------------------------------------------\n# @AXON.before_task - question in, chat prompt out. All the I/O lives here.\n# ---------------------------------------------------------------------------\n\n@AXON.before_task\nasync def situate(input):\n    \"\"\"Recall, go and learn if memory is thin, then build the prompt.\"\"\"\n    tid, _ = ambient_trace()\n    d = AXON.dendrite\n    question = input[\"question\"]\n    top_k = int(input.get(\"top_k\", TOP_K))\n\n    passages, source, stored, pages = [], \"memory\", 0, []\n    if not input.get(\"force_web\"):\n        known = await d.recall(engram_id=ENGRAM_ID,\n                               query={\"text\": question, \"top_k\": top_k},\n                               deadline_ms=2000)\n        passages = _passages(known.hits)\n\n    if input.get(\"force_web\") or not _covers(question, passages):\n        source = \"web\"\n        found = await d.call_tool(effector_id=EFFECTOR_ID, tool=\"search\",\n                                  args={\"query\": question,\n                                        \"max_results\": SEARCH_RESULTS},\n                                  deadline_ms=60_000)\n        if found.error:\n            raise RuntimeError(f\"search failed: {found.error}\")\n\n        for url in _urls((found.result or {}).get(\"response\", \"\"), FETCH_PAGES):\n            page = await d.call_tool(effector_id=EFFECTOR_ID, tool=\"fetch\",\n                                     args={\"url\": url,\n                                           \"max_length\": FETCH_CHARS},\n                                     deadline_ms=60_000)\n            if page.error:              # a dead link is not a failed task\n                continue\n            body = (page.result or {}).get(\"response\", \"\")\n            if len(body) < MIN_PAGE_CHARS:   # a stub, a paywall, a redirect\n                continue\n            title = _title(body, url)\n            stamp = datetime.now(timezone.utc).isoformat()\n            chunks = _chunks(body)\n            if chunks:\n                pages.append(url)\n            for i, chunk in enumerate(chunks):\n                # merge_key makes re-reading a page idempotent. No ack is\n                # awaited - nothing downstream needs the receipt.\n                await d.imprint(engram_id=ENGRAM_ID, op=\"upsert\",\n                                merge_key=f\"{url}#{i}\",\n                                entry={\"text\": chunk, \"url\": url,\n                                       \"title\": title, \"chunk_index\": i,\n                                       \"fetched_at\": stamp},\n                                await_ack=False)\n                stored += 1\n\n        # The same recall as above. Both paths converge here.\n        fresh = await d.recall(engram_id=ENGRAM_ID,\n                               query={\"text\": question, \"top_k\": top_k},\n                               deadline_ms=2000)\n        passages = _passages(fresh.hits)\n\n    _PENDING[tid] = {\"question\": question, \"source\": source,\n                     \"indexed\": stored, \"pages\": pages, \"passages\": passages}\n\n    if not passages:\n        # No empty \"Context passages:\" header here. Showing the model a\n        # heading with nothing under it invites it to talk about the\n        # heading, which is the same failure the system prompt is written\n        # to avoid. Tell it what happened instead.\n        return {\"messages\": [\n            {\"role\": \"system\", \"content\": SYSTEM_PROMPT},\n            {\"role\": \"user\", \"content\": (\n                f\"Question: {question}\\n\\n\"\n                \"Nothing turned up for this one. Say so in a sentence, and \"\n                \"suggest a narrower question that might land.\")}]}\n\n    blocks = \"\\n\\n\".join(\n        f\"[{p['n']}] ({p.get('title') or p.get('url')})\\n{p['text']}\"\n        for p in passages)\n    return {\"messages\": [\n        {\"role\": \"system\", \"content\": SYSTEM_PROMPT},\n        {\"role\": \"user\", \"content\": (\n            f\"Context passages:\\n\\n{blocks}\\n\\nQuestion: {question}\")}]}\n\n\n# ---------------------------------------------------------------------------\n# @AXON.detects_output - the reply is the answer. Echo the hook's state.\n# ---------------------------------------------------------------------------\n\n@AXON.detects_output\ndef answer(raw):\n    tid, _ = ambient_trace()\n    st = _PENDING.pop(tid, {})\n    text = (raw.get(\"response\") or \"\").strip() or \"(empty reply)\"\n    passages = st.get(\"passages\") or []\n\n    # Report what the answer CITED, not what the prompt offered. Echoing\n    # every passage fed in makes an unused page look like evidence for a\n    # claim it had nothing to do with - which is worse than showing no\n    # sources at all, because it reads as a citation. Fall back to the full\n    # set only when the model cited nothing, where \"here is what it saw\" is\n    # the honest reading.\n    cited = {int(n) for n in _CITE.findall(text)}\n    used = [p for p in passages if p[\"n\"] in cited] or passages\n\n    return {\n        \"question\": st.get(\"question\"),\n        \"answer\": text,\n        \"source\": st.get(\"source\", \"memory\"),\n        \"indexed\": st.get(\"indexed\", 0),\n        \"pages\": st.get(\"pages\") or [],\n        \"cited\": bool(cited),\n        \"sources\": [{\"n\": p[\"n\"], \"url\": p[\"url\"], \"title\": p[\"title\"],\n                     \"score\": p[\"score\"]}\n                    for p in used],\n    }\n\n\n# ---------------------------------------------------------------------------\n# @AXON.host.on_agent_output - THE CHAIN. One link: conclude the trace.\n# ---------------------------------------------------------------------------\n\n@AXON.host.on_agent_output(neuron=\"rag\")\nasync def conclude(sig):\n    \"\"\"FINAL resolves the CLI's Pathway. A longer chain would dispatch the\n    next TASK here instead - see 14-agent, where this same decorator hands\n    work from the planner to the research and coding neurons.\"\"\"\n    await AXON.dendrite.emit_final(\n        trace_id=sig.trace_id, parent_id=sig.id, neuron=\"rag\",\n        result=sig.payload.get(\"output\", {}),\n    )\n"
};
